def icon(name: str, extra_class: str = "") -> str:
    """Return the inline SVG for a named icon."""
    markup = ICONS[name.replace("-", "_")]
    if extra_class:
        markup = markup.replace(
            'class="lucide lucide-', f'class="{extra_class} lucide lucide-', 1
        )
    return markup
